// Wallet Card front end. Vanilla ES module, no framework, no build step.
// Rule: user text only ever goes into the DOM through textContent or attribute
// setters. The only markup we insert is the QR SVG generated by the library.
import { sanitizeCard, TEXT_FIELDS } from './fields.js';
import { buildVCard, QR_WARN_BYTES } from './vcard.js';
import {
  DEFAULT_COLORS,
  PRESETS,
  contrastRatio,
  ensureContrast,
  normalizeHex,
  MIN_TEXT_CONTRAST,
  MIN_LABEL_CONTRAST,
} from './colors.js';
import { qrPayload, payloadBytes, qrSvgElement, qrMatrix } from './qr.js';

const STORAGE_KEY = 'walletcard.card.v1';
const IOS_HINT_KEY = 'walletcard.iosHintSeen';
const $ = (id) => document.getElementById(id);
const reducedMotion = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;

// ---------- Safe storage (every read and write in try/catch) ----------
const storage = {
  get(key) {
    try {
      return window.localStorage.getItem(key);
    } catch {
      return null;
    }
  },
  set(key, value) {
    try {
      window.localStorage.setItem(key, value);
      return true;
    } catch {
      return false;
    }
  },
};

function normalizeColors(c) {
  const src = c && typeof c === 'object' ? c : {};
  return {
    background: normalizeHex(src.background) || DEFAULT_COLORS.background,
    foreground: normalizeHex(src.foreground) || DEFAULT_COLORS.foreground,
    label: normalizeHex(src.label) || DEFAULT_COLORS.label,
  };
}

function loadCard() {
  const raw = storage.get(STORAGE_KEY);
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    const { card } = sanitizeCard(parsed, { keepPhoto: true, requireName: false });
    if (!card.name) return null;
    card.colors = normalizeColors(parsed.colors);
    card.qrMode = ['contact', 'website', 'linkedin'].includes(parsed.qrMode) ? parsed.qrMode : 'contact';
    return card;
  } catch {
    return null;
  }
}

function saveCard(card) {
  return storage.set(STORAGE_KEY, JSON.stringify(card));
}

// ---------- State ----------
let saved = loadCard();
let photo = saved?.photo || '';
let deferredInstall = null;
let wakeLock = null;
let prepared = { image: null, vcf: null }; // pre-built files so share() runs inside the tap
let step = 1;
const STEPS = 3;
const STEP_FIELDS = {
  1: ['name', 'title', 'company', 'location'],
  2: ['email', 'phone', 'website', 'linkedin'],
  3: ['tagline', 'bio'],
};
let timerStart = 0;
let timerId = 0;

const form = $('card-form');
const fieldEl = (name) => form.elements.namedItem(name);

// ---------- Helpers ----------
function setText(el, text) {
  el.textContent = text || '';
  el.hidden = !text;
}

function replay(el, cls) {
  if (!el || reducedMotion()) return;
  el.classList.remove(cls);
  void el.offsetWidth; // restart the animation
  el.classList.add(cls);
}

let toastTimer;
function toast(message) {
  const el = $('toast');
  el.textContent = message;
  el.hidden = false;
  replay(el, 'show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => {
    el.hidden = true;
  }, 3200);
}

function applyCardColors(el, colors) {
  el.style.setProperty('--card-bg', colors.background);
  el.style.setProperty('--card-fg', colors.foreground);
  el.style.setProperty('--card-label', colors.label);
}

function setThemeColor(color) {
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content', color);
}

const isCoarsePointer = () => window.matchMedia('(pointer: coarse)').matches;
const isStandalone = () => window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
const isIOS = () => /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);

function slug(s) {
  const base = String(s || 'card')
    .normalize('NFC')
    .replace(/[^\p{L}\p{M}\p{N}\s-]/gu, '') // keep letters in any script (Assamese, Hindi, Arabic)
    .trim()
    .replace(/\s+/g, '-')
    .toLowerCase();
  return base || 'card';
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.rel = 'noopener';
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

async function shareFiles(file, title) {
  if (navigator.canShare && navigator.share && navigator.canShare({ files: [file] })) {
    try {
      await navigator.share({ files: [file], title });
      return true;
    } catch (err) {
      if (err && err.name === 'AbortError') return true; // user closed the sheet
      return false;
    }
  }
  return false;
}

// ---------- Views (with View Transitions where supported) ----------
function paperColor() {
  return getComputedStyle(document.documentElement).getPropertyValue('--paper').trim() || '#fff8ec';
}

function showView(name) {
  const apply = () => {
    for (const v of ['welcome', 'editor', 'card']) $(`view-${v}`).hidden = v !== name;
    document.body.dataset.view = name;
    window.scrollTo(0, 0);
  };
  let done = Promise.resolve();
  if (document.startViewTransition && !reducedMotion() && document.body.dataset.view !== 'loading') {
    const vt = document.startViewTransition(apply);
    vt.ready.catch(() => {}); // aborted transitions (e.g. phone rotated mid-way) are harmless
    done = vt.finished.catch(() => {});
  } else {
    apply();
  }
  if (name === 'card') requestWakeLock();
  else releaseWakeLock();
  if (name !== 'card') setThemeColor(paperColor());
  if (name !== 'editor') stopTimer();
  $('cancel-edit').hidden = !(name === 'editor' && saved);
  return done;
}

// ---------- Stopwatch ("your card in about a minute") ----------
function formatClock(ms) {
  const s = Math.floor(ms / 1000);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}
function formatDuration(ms) {
  const s = Math.max(1, Math.round(ms / 1000));
  if (s < 60) return `${s} second${s === 1 ? '' : 's'}`;
  const m = Math.floor(s / 60);
  const r = s % 60;
  return r ? `${m} min ${r} s` : `${m} min`;
}
function startTimer() {
  timerStart = performance.now();
  clearInterval(timerId);
  $('timer').textContent = '0:00';
  timerId = setInterval(() => {
    $('timer').textContent = formatClock(performance.now() - timerStart);
  }, 1000);
}
function stopTimer() {
  clearInterval(timerId);
  return timerStart ? performance.now() - timerStart : 0;
}

// ---------- Buddy (the mascot's speech bubble) ----------
const BUDDY = {
  1: 'Start with your name. That is the only must.',
  2: 'How should people reach you? Fill in any you like.',
  3: 'Pick a look. One tap is plenty. Then save!',
};
let buddyLast = '';
function buddy(text) {
  if (text === buddyLast) return;
  buddyLast = text;
  const el = $('buddy-text');
  el.textContent = text;
  replay(el, 'bump');
}
function firstName(name) {
  return String(name || '').trim().split(/\s+/)[0] || '';
}

// ---------- Steps ----------
function goToStep(n, { focus = true } = {}) {
  const next = Math.min(STEPS, Math.max(1, n));
  const dir = next >= step ? 'enter-next' : 'enter-prev';
  step = next;
  for (const sec of form.querySelectorAll('.step')) {
    const isActive = Number(sec.dataset.step) === step;
    sec.hidden = !isActive;
    sec.classList.remove('enter-next', 'enter-prev', 'shake');
    if (isActive) replay(sec, dir);
  }
  for (const dot of document.querySelectorAll('.step-dot')) {
    const n2 = Number(dot.dataset.goto);
    if (n2 === step) dot.setAttribute('aria-current', 'step');
    else dot.removeAttribute('aria-current');
    dot.dataset.done = String(n2 < step);
    dot.setAttribute('aria-label', `Step ${n2}: ${dot.querySelector('.dot-label').textContent}${n2 < step ? ' (done)' : ''}`);
  }
  $('stepper-fill').style.width = `${((step - 1) / (STEPS - 1)) * 100}%`;
  $('step-back').hidden = step === 1;
  $('step-next-label').textContent = step === STEPS ? 'Save my card' : 'Next';
  $('step-next').classList.toggle('btn-save', step === STEPS);

  const name = fieldEl('name').value;
  buddy(step === 1 && name.trim() ? `Nice to meet you, ${firstName(name)}!` : BUDDY[step]);

  if (focus) {
    const heading = form.querySelector(`.step[data-step="${step}"] .step-title`);
    heading?.setAttribute('tabindex', '-1');
    heading?.focus({ preventScroll: true });
    const top = form.getBoundingClientRect().top + window.scrollY - 90;
    if (window.scrollY > top) window.scrollTo({ top, behavior: reducedMotion() ? 'auto' : 'smooth' });
  }
}

function stepErrors(n) {
  const { raw } = readForm();
  const { errors } = sanitizeCard(raw);
  const out = {};
  for (const key of STEP_FIELDS[n]) if (errors[key]) out[key] = errors[key];
  return out;
}

function nextStep() {
  const errors = stepErrors(step);
  if (Object.keys(errors).length) {
    showErrors(errors);
    replay(form.querySelector(`.step[data-step="${step}"]`), 'shake');
    buddy(errors.name ? 'I need a name to put on the card.' : 'Something needs a quick fix.');
    return;
  }
  goToStep(step + 1);
}

// ---------- Editor ----------
function fillForm(card) {
  for (const key of TEXT_FIELDS) fieldEl(key).value = card?.[key] || '';
  // New cards start on a cheerful preset; saved cards keep their own colours.
  const colors = normalizeColors(card ? card.colors : PRESETS.find((p) => p.id === 'sunny'));
  fieldEl('background').value = colors.background;
  fieldEl('foreground').value = colors.foreground;
  fieldEl('label').value = colors.label;
  photo = card?.photo || '';
  renderPhotoThumb();
  clearErrors();
  syncPresetSelection();
}

function readForm() {
  const raw = {};
  for (const key of TEXT_FIELDS) raw[key] = fieldEl(key).value;
  return {
    raw,
    colors: normalizeColors({
      background: fieldEl('background').value,
      foreground: fieldEl('foreground').value,
      label: fieldEl('label').value,
    }),
  };
}

function renderPreview() {
  const { raw, colors } = readForm();
  const { card } = sanitizeCard(raw, { requireName: false });
  const pv = $('preview');
  applyCardColors(pv, colors);
  $('pv-name').textContent = card.name || 'Your name';
  $('pv-name').classList.toggle('placeholder', !card.name);
  setText($('pv-title'), card.title);
  setText($('pv-company'), [card.company, card.location].filter(Boolean).join('  ·  '));
  setText($('pv-tagline'), card.tagline);
  const list = $('pv-contact');
  list.replaceChildren();
  for (const v of [card.email, card.phone, card.website?.replace(/^https?:\/\//, ''), card.linkedin?.replace(/^https?:\/\/(www\.)?/, '')]) {
    if (!v) continue;
    const li = document.createElement('li');
    li.textContent = v;
    list.append(li);
  }
  const img = $('pv-photo');
  if (photo) {
    img.src = photo;
    img.hidden = false;
  } else {
    img.removeAttribute('src');
    img.hidden = true;
  }
  renderContrastNote(colors);
}

function renderContrastNote(colors) {
  const text = contrastRatio(colors.foreground, colors.background);
  const label = contrastRatio(colors.label, colors.background);
  const problems = [];
  if (text < MIN_TEXT_CONTRAST) problems.push(`text is ${text.toFixed(1)}:1 (needs ${MIN_TEXT_CONTRAST}:1)`);
  if (label < MIN_LABEL_CONTRAST) problems.push(`labels are ${label.toFixed(1)}:1 (needs ${MIN_LABEL_CONTRAST}:1)`);
  $('contrast-note').hidden = problems.length === 0;
  $('contrast-text').textContent = problems.length ? `Hard to read: ${problems.join(', ')}.` : '';
}

function fixContrast() {
  const { colors } = readForm();
  fieldEl('foreground').value = ensureContrast(colors.foreground, colors.background, MIN_TEXT_CONTRAST);
  fieldEl('label').value = ensureContrast(colors.label, colors.background, MIN_LABEL_CONTRAST);
  renderPreview();
  replay($('preview'), 'bump');
}

function clearErrors() {
  for (const el of form.querySelectorAll('.field-error')) {
    el.hidden = true;
    el.textContent = '';
  }
  for (const el of form.querySelectorAll('[aria-invalid]')) el.removeAttribute('aria-invalid');
}

function showErrors(errors) {
  clearErrors();
  let first = null;
  for (const [key, message] of Object.entries(errors)) {
    const input = fieldEl(key);
    const err = $(`err-${key}`);
    if (input) input.setAttribute('aria-invalid', 'true');
    if (err) {
      err.textContent = message;
      err.hidden = false;
    }
    if (!first && input) first = input;
  }
  first?.focus();
}

// ---------- Presets ----------
function renderPresets() {
  const wrap = $('presets');
  for (const p of PRESETS) {
    const label = document.createElement('label');
    label.className = 'preset';
    const input = document.createElement('input');
    input.type = 'radio';
    input.name = 'preset';
    input.value = p.id;
    const sw = document.createElement('span');
    sw.className = 'swatch';
    sw.setAttribute('aria-hidden', 'true');
    sw.style.setProperty('--sw-bg', p.background);
    sw.style.setProperty('--sw-fg', p.foreground);
    sw.style.setProperty('--sw-label', p.label);
    sw.append(document.createElement('i'), document.createElement('i'));
    const name = document.createElement('span');
    name.textContent = p.name;
    label.append(input, sw, name);
    wrap.append(label);
  }
  wrap.addEventListener('change', (e) => {
    const p = PRESETS.find((x) => x.id === e.target.value);
    if (!p) return;
    fieldEl('background').value = p.background;
    fieldEl('foreground').value = p.foreground;
    fieldEl('label').value = p.label;
    renderPreview();
    replay($('preview'), 'bump');
    buddy(`${p.name}. Good pick!`);
  });
}

function syncPresetSelection() {
  const { colors } = readForm();
  const match = PRESETS.find((p) => p.background === colors.background && p.foreground === colors.foreground && p.label === colors.label);
  for (const input of form.querySelectorAll('input[name="preset"]')) input.checked = Boolean(match && input.value === match.id);
}

// ---------- Save ----------
function saveFromForm() {
  const { raw, colors } = readForm();
  const { card, errors } = sanitizeCard({ ...raw, photo }, { keepPhoto: true });
  if (Object.keys(errors).length) {
    const badStep = Number(Object.entries(STEP_FIELDS).find(([, keys]) => keys.some((k) => errors[k]))?.[0] || 1);
    goToStep(badStep, { focus: false });
    showErrors(errors);
    replay(form.querySelector(`.step[data-step="${badStep}"]`), 'shake');
    buddy('Almost! One thing needs fixing.');
    return;
  }
  const wasNew = !saved;
  card.colors = colors;
  card.qrMode = saved?.qrMode || 'contact';
  if (card.qrMode === 'website' && !card.website) card.qrMode = 'contact';
  if (card.qrMode === 'linkedin' && !card.linkedin) card.qrMode = 'contact';
  const ok = saveCard(card);
  saved = card;
  const elapsed = stopTimer();
  openMyCard().then(() => celebrate(wasNew, elapsed, ok));
}

function onSubmit(event) {
  event.preventDefault();
  if (step < STEPS) nextStep();
  else saveFromForm();
}

// ---------- Celebration ----------
const CONFETTI_COLORS = ['#ffd23f', '#ff7a59', '#4cd4a8', '#7cc6ff', '#b9a3ff', '#ff9ec7'];
let celebrateTimer;

function burstConfetti() {
  if (reducedMotion()) return;
  const box = $('confetti');
  box.replaceChildren();
  const count = window.innerWidth < 600 ? 60 : 90;
  for (let i = 0; i < count; i++) {
    const c = document.createElement('span');
    const shape = Math.random();
    c.className = `confetto${shape < 0.3 ? ' round' : shape < 0.55 ? ' strip' : ''}`;
    const angle = Math.random() * Math.PI * 2;
    const dist = 140 + Math.random() * Math.min(window.innerWidth, 700) * 0.55;
    c.style.setProperty('--x', `${Math.cos(angle) * dist}px`);
    c.style.setProperty('--y', `${Math.sin(angle) * dist * 0.8 - 120}px`);
    c.style.setProperty('--r', `${Math.round(Math.random() * 720 - 360)}deg`);
    c.style.setProperty('--d', `${1200 + Math.random() * 900}ms`);
    c.style.setProperty('--c', CONFETTI_COLORS[i % CONFETTI_COLORS.length]);
    box.append(c);
  }
  setTimeout(() => box.replaceChildren(), 2400);
}

function celebrate(wasNew, elapsed, storedOk) {
  const overlay = $('celebrate');
  $('celebrate-title').textContent = wasNew ? 'Card ready!' : 'Card updated!';
  const time = $('celebrate-time');
  time.replaceChildren();
  if (!storedOk) {
    time.textContent = 'This device blocked saving, so your card lasts until you close the app.';
  } else if (elapsed > 0) {
    time.append(wasNew ? 'Done in ' : 'Updated in ');
    const strong = document.createElement('strong');
    strong.textContent = formatDuration(elapsed);
    time.append(strong, '. Back to meeting people.');
  } else {
    time.textContent = 'Saved on this device.';
  }
  overlay.hidden = false;
  burstConfetti();
  $('celebrate-close').focus({ preventScroll: true });
  clearTimeout(celebrateTimer);
  celebrateTimer = setTimeout(closeCelebrate, 4200);
}

function closeCelebrate() {
  clearTimeout(celebrateTimer);
  if ($('celebrate').hidden) return;
  $('celebrate').hidden = true;
  $('confetti').replaceChildren();
  maybeShowIosHint();
}

// ---------- Photo ----------
function renderPhotoThumb() {
  const thumb = $('photo-thumb');
  if (photo) {
    thumb.src = photo;
    thumb.hidden = false;
    $('photo-remove').hidden = false;
  } else {
    thumb.removeAttribute('src');
    thumb.hidden = true;
    $('photo-remove').hidden = true;
  }
}

async function loadImage(file) {
  if (typeof createImageBitmap === 'function') {
    try {
      return await createImageBitmap(file);
    } catch {
      /* fall through to <img> */
    }
  }
  const url = URL.createObjectURL(file);
  try {
    const img = new Image();
    img.decoding = 'async';
    img.src = url;
    await img.decode();
    return img;
  } finally {
    URL.revokeObjectURL(url);
  }
}

async function onPhotoChange() {
  const file = $('f-photo').files?.[0];
  if (!file) return;
  if (!/^image\//.test(file.type)) {
    toast('That file is not an image.');
    return;
  }
  if (file.size > 20 * 1024 * 1024) {
    toast('That image is over 20 MB. Choose a smaller one.');
    return;
  }
  try {
    const img = await loadImage(file);
    const w = img.width;
    const h = img.height;
    const side = Math.min(w, h);
    const canvas = document.createElement('canvas');
    canvas.width = 180;
    canvas.height = 180;
    const ctx = canvas.getContext('2d');
    ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(img, (w - side) / 2, (h - side) / 2, side, side, 0, 0, 180, 180);
    photo = canvas.toDataURL('image/jpeg', 0.86);
    img.close?.();
    renderPhotoThumb();
    renderPreview();
    replay($('preview'), 'bump');
    buddy('Looking sharp!');
  } catch {
    toast('Could not read that image. Try a JPEG or PNG.');
  } finally {
    $('f-photo').value = '';
  }
}

// ---------- Card tilt (fine pointers only) ----------
function setupTilt() {
  const area = $('tilt');
  const card = $('preview');
  area.addEventListener('pointermove', (e) => {
    if (e.pointerType !== 'mouse' || reducedMotion()) return;
    const r = card.getBoundingClientRect();
    const px = (e.clientX - r.left) / r.width;
    const py = (e.clientY - r.top) / r.height;
    card.style.setProperty('--ry', `${(px - 0.5) * 14}deg`);
    card.style.setProperty('--rx', `${(0.5 - py) * 12}deg`);
    card.style.setProperty('--mx', `${px * 100}%`);
    card.style.setProperty('--my', `${py * 100}%`);
  });
  area.addEventListener('pointerleave', () => {
    card.style.setProperty('--rx', '0deg');
    card.style.setProperty('--ry', '0deg');
    card.style.removeProperty('--mx');
    card.style.removeProperty('--my');
  });
}

// ---------- My Card ----------
const CAPTIONS = {
  contact: 'Scan to save my contact',
  website: 'Scan to open my website',
  linkedin: 'Scan to open my LinkedIn',
};

function currentMode() {
  const checked = document.querySelector('input[name="qrmode"]:checked');
  return checked ? checked.value : 'contact';
}

async function renderMyCard() {
  const card = saved;
  if (!card) return;
  const root = document.body;
  applyCardColors(root, card.colors);
  setThemeColor(card.colors.background);

  $('mc-name').textContent = card.name;
  setText($('mc-title'), card.title);
  setText($('mc-company'), [card.company, card.location].filter(Boolean).join('  ·  '));
  setText($('mc-tagline'), card.tagline);
  const img = $('mc-photo');
  if (card.photo) {
    img.src = card.photo;
    img.hidden = false;
  } else {
    img.removeAttribute('src');
    img.hidden = true;
  }

  $('qm-website').disabled = !card.website;
  $('qm-linkedin').disabled = !card.linkedin;
  let mode = card.qrMode || 'contact';
  if ((mode === 'website' && !card.website) || (mode === 'linkedin' && !card.linkedin)) mode = 'contact';
  $(`qm-${mode}`).checked = true;
  $('qr-mode').dataset.mode = mode;
  $('qr-mode').hidden = !card.website && !card.linkedin;
  $('act-share').hidden = !(card.website || card.linkedin);

  await renderQr(card, mode);
}

async function renderQr(card, mode, { animate = false } = {}) {
  const payload = qrPayload(card, mode);
  const bytes = payloadBytes(payload);
  const box = $('qr');
  try {
    const svg = await qrSvgElement(payload);
    box.replaceChildren(svg);
    box.setAttribute('aria-label', `QR code. ${CAPTIONS[mode]}.`);
    if (animate) replay(box, 'swap');
  } catch {
    box.replaceChildren();
    const p = document.createElement('p');
    p.className = 'qr-error';
    p.textContent = 'Could not draw the QR code. Reload the app and try again.';
    box.append(p);
  }
  $('qr-caption').textContent = CAPTIONS[mode];

  const warn = $('qr-warning');
  if (mode === 'contact' && bytes > QR_WARN_BYTES) {
    const alt = card.website ? 'Website' : card.linkedin ? 'LinkedIn' : null;
    warn.textContent = `Your contact details make a dense QR code (${bytes} bytes), which can be hard to scan from across a table.${
      alt ? ` Switch to ${alt} mode for a simpler code, or shorten some fields.` : ' Try shortening some fields, or add a website.'
    }`;
    warn.hidden = false;
  } else {
    warn.hidden = true;
  }

  prepared = { image: null, vcf: null };
  prepareFiles(card, payload).catch(() => {});
}

async function prepareFiles(card, payload) {
  const vcfText = buildVCard(card, { compact: false });
  prepared.vcf = new File([vcfText], `${slug(card.name)}.vcf`, { type: 'text/vcard' });
  const blob = await renderCardImage(card, payload);
  if (blob) prepared.image = new File([blob], `${slug(card.name)}-card.png`, { type: 'image/png' });
}

function onModeChange() {
  if (!saved) return;
  saved.qrMode = currentMode();
  $('qr-mode').dataset.mode = saved.qrMode;
  saveCard(saved);
  renderQr(saved, saved.qrMode, { animate: true });
}

function openMyCard() {
  const done = showView('card');
  renderMyCard();
  return done;
}

function openEditor({ fresh = false } = {}) {
  fillForm(saved);
  document.body.style.removeProperty('--card-bg');
  document.body.style.removeProperty('--card-fg');
  document.body.style.removeProperty('--card-label');
  showView('editor');
  goToStep(1, { focus: false });
  renderPreview();
  startTimer();
  if (fresh) setTimeout(() => fieldEl('name').focus(), reducedMotion() ? 0 : 450);
}

function openWelcome() {
  showView('welcome');
}

// ---------- Export: image (1080x1350) ----------
const FONT_STACK = '"Fredoka Variable", -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, Roboto, "Noto Sans", "Noto Sans Bengali", "Noto Sans Devanagari", "Noto Sans Arabic", sans-serif';

function wrapLines(ctx, text, maxWidth, maxLines) {
  const words = String(text || '').split(/\s+/).filter(Boolean);
  const lines = [];
  let line = '';
  for (const w of words) {
    const test = line ? `${line} ${w}` : w;
    if (ctx.measureText(test).width <= maxWidth || !line) {
      line = test;
    } else {
      lines.push(line);
      line = w;
    }
  }
  if (line) lines.push(line);
  if (lines.length > maxLines) {
    const kept = lines.slice(0, maxLines);
    let last = kept[maxLines - 1];
    while (last.length > 1 && ctx.measureText(`${last}...`).width > maxWidth) last = last.slice(0, -1);
    kept[maxLines - 1] = `${last.trimEnd()}...`;
    return kept;
  }
  return lines;
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

async function renderCardImage(card, payload) {
  try {
    await document.fonts.load(`700 76px "Fredoka Variable"`);
  } catch {
    /* system font fallback is fine */
  }
  const W = 1080;
  const H = 1350;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  const { background, foreground, label } = card.colors;
  const pad = 88;

  ctx.fillStyle = background;
  ctx.fillRect(0, 0, W, H);

  let y = 96;
  if (card.photo) {
    const img = new Image();
    img.src = card.photo;
    try {
      await img.decode();
      const s = 168;
      ctx.save();
      ctx.beginPath();
      ctx.arc(pad + s / 2, y + s / 2, s / 2, 0, Math.PI * 2);
      ctx.clip();
      ctx.drawImage(img, pad, y, s, s);
      ctx.restore();
      ctx.lineWidth = 6;
      ctx.strokeStyle = foreground;
      ctx.beginPath();
      ctx.arc(pad + s / 2, y + s / 2, s / 2, 0, Math.PI * 2);
      ctx.stroke();
      y += s + 40;
    } catch {
      /* skip photo */
    }
  }

  ctx.textBaseline = 'top';
  ctx.textAlign = 'left';
  ctx.direction = 'inherit';
  const maxW = W - pad * 2;

  ctx.fillStyle = foreground;
  ctx.font = `700 80px ${FONT_STACK}`;
  for (const line of wrapLines(ctx, card.name, maxW, 2)) {
    ctx.fillText(line, pad, y);
    y += 90;
  }
  if (card.title) {
    ctx.font = `600 40px ${FONT_STACK}`;
    for (const line of wrapLines(ctx, card.title, maxW, 1)) {
      ctx.fillText(line, pad, y + 4);
      y += 54;
    }
  }
  const org = [card.company, card.location].filter(Boolean).join('  ·  ');
  if (org) {
    ctx.fillStyle = label;
    ctx.font = `600 34px ${FONT_STACK}`;
    for (const line of wrapLines(ctx, org, maxW, 1)) {
      ctx.fillText(line, pad, y + 6);
      y += 48;
    }
  }

  // QR panel anchored to the bottom; the tagline goes between if there is room.
  const caption = CAPTIONS[currentMode()] || CAPTIONS.contact;
  const captionH = 60;
  const bottomPad = 72;
  const maxPanel = 720; // grows into free space: bigger modules scan better from across a table
  const topOfQrArea = y + 40;
  const panel = Math.max(420, Math.min(maxPanel, H - bottomPad - captionH - topOfQrArea));
  const panelX = (W - panel) / 2;
  const panelY = H - bottomPad - captionH - panel;

  if (card.tagline && panelY - y > 70) {
    ctx.fillStyle = foreground;
    ctx.globalAlpha = 0.86;
    ctx.font = `500 34px ${FONT_STACK}`;
    const room = Math.floor((panelY - y - 40) / 46);
    for (const line of wrapLines(ctx, card.tagline, maxW, Math.max(1, Math.min(2, room)))) {
      ctx.fillText(line, pad, y + 14);
      y += 46;
    }
    ctx.globalAlpha = 1;
  }

  // Sticker-style panel: offset shadow, white fill, ink outline.
  ctx.fillStyle = foreground;
  ctx.globalAlpha = 0.35;
  roundRect(ctx, panelX + 12, panelY + 12, panel, panel, 40);
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.fillStyle = '#ffffff';
  roundRect(ctx, panelX, panelY, panel, panel, 40);
  ctx.fill();
  ctx.lineWidth = 6;
  ctx.strokeStyle = '#1f1a33';
  ctx.stroke();

  const m = qrMatrix(payload);
  const quiet = 4;
  const modulePx = Math.floor((panel - 40) / (m.size + quiet * 2));
  const qrPx = modulePx * (m.size + quiet * 2);
  const ox = Math.round(panelX + (panel - qrPx) / 2) + quiet * modulePx;
  const oy = Math.round(panelY + (panel - qrPx) / 2) + quiet * modulePx;
  ctx.fillStyle = '#000000';
  for (let r = 0; r < m.size; r++) {
    let c = 0;
    while (c < m.size) {
      if (!m.isDark(r, c)) {
        c++;
        continue;
      }
      const start = c;
      while (c < m.size && m.isDark(r, c)) c++;
      ctx.fillRect(ox + start * modulePx, oy + r * modulePx, (c - start) * modulePx, modulePx);
    }
  }

  ctx.fillStyle = label;
  ctx.font = `600 34px ${FONT_STACK}`;
  ctx.textAlign = 'center';
  ctx.fillText(caption, W / 2, panelY + panel + 26);

  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function onSaveImage() {
  if (!saved) return;
  let file = prepared.image;
  if (!file) {
    const blob = await renderCardImage(saved, qrPayload(saved, currentMode()));
    if (!blob) {
      toast('Could not create the image.');
      return;
    }
    file = new File([blob], `${slug(saved.name)}-card.png`, { type: 'image/png' });
    prepared.image = file;
  }
  if (isCoarsePointer() && (await shareFiles(file, saved.name))) return;
  downloadBlob(file, file.name);
  toast('Image downloaded.');
}

function onAddContact() {
  if (!saved) return;
  const file = prepared.vcf || new File([buildVCard(saved, { compact: false })], `${slug(saved.name)}.vcf`, { type: 'text/vcard' });
  // Inside an installed iOS app, downloads are unreliable; the share sheet can hand the file to Contacts.
  if (isIOS() && isStandalone()) {
    shareFiles(file, saved.name).then((ok) => {
      if (!ok) downloadBlob(file, file.name);
    });
    return;
  }
  downloadBlob(file, file.name);
}

async function onShareLink() {
  if (!saved) return;
  const mode = currentMode();
  const url = mode === 'linkedin' && saved.linkedin ? saved.linkedin : saved.website || saved.linkedin;
  if (!url) return;
  const text = [saved.name, saved.title].filter(Boolean).join(', ');
  if (navigator.share) {
    try {
      await navigator.share({ title: saved.name, text, url });
      return;
    } catch (err) {
      if (err && err.name === 'AbortError') return;
    }
  }
  try {
    await navigator.clipboard.writeText(url);
    toast('Link copied.');
  } catch {
    toast(url);
  }
}

// ---------- Wake lock (keeps the screen on while showing the QR) ----------
async function requestWakeLock() {
  try {
    if ('wakeLock' in navigator && document.visibilityState === 'visible' && !wakeLock) {
      wakeLock = await navigator.wakeLock.request('screen');
      wakeLock.addEventListener('release', () => {
        wakeLock = null;
      });
    }
  } catch {
    wakeLock = null;
  }
}
function releaseWakeLock() {
  wakeLock?.release().catch(() => {});
  wakeLock = null;
}

// ---------- Install ----------
function maybeShowIosHint() {
  if (!isIOS() || isStandalone()) return;
  if (storage.get(IOS_HINT_KEY)) return;
  $('ios-hint').hidden = false;
}

function setupInstall() {
  window.addEventListener('beforeinstallprompt', (event) => {
    event.preventDefault();
    deferredInstall = event;
    $('install-btn').hidden = false;
  });
  window.addEventListener('appinstalled', () => {
    deferredInstall = null;
    $('install-btn').hidden = true;
    toast('Installed. Open Wallet Card from your home screen.');
  });
  $('install-btn').addEventListener('click', async () => {
    if (!deferredInstall) return;
    deferredInstall.prompt();
    try {
      await deferredInstall.userChoice;
    } catch {
      /* ignore */
    }
    deferredInstall = null;
    $('install-btn').hidden = true;
  });
  $('ios-hint-close').addEventListener('click', () => {
    $('ios-hint').hidden = true;
    storage.set(IOS_HINT_KEY, '1');
  });

  if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('sw.js').catch(() => {});
    });
  }
}

// ---------- Wire up ----------
function onFormInput(e) {
  const t = e.target;
  if (t.name === 'preset') return;
  if (t.getAttribute('aria-invalid')) {
    t.removeAttribute('aria-invalid');
    const err = $(`err-${t.name}`);
    if (err) err.hidden = true;
  }
  if (t.type === 'color') syncPresetSelection();
  if (t.name === 'name' && step === 1) {
    buddy(t.value.trim() ? `Nice to meet you, ${firstName(t.value)}!` : BUDDY[1]);
  }
  renderPreview();
}

function init() {
  renderPresets();
  form.addEventListener('input', onFormInput);
  form.addEventListener('submit', onSubmit);
  $('step-back').addEventListener('click', () => goToStep(step - 1));
  for (const dot of document.querySelectorAll('.step-dot')) {
    dot.addEventListener('click', () => {
      const target = Number(dot.dataset.goto);
      if (target > step && Object.keys(stepErrors(step)).length) {
        nextStep(); // shows what needs fixing first
        return;
      }
      goToStep(target);
    });
  }
  $('f-photo').addEventListener('change', onPhotoChange);
  $('photo-remove').addEventListener('click', () => {
    photo = '';
    renderPhotoThumb();
    renderPreview();
  });
  $('contrast-fix').addEventListener('click', fixContrast);
  $('cancel-edit').addEventListener('click', openMyCard);
  $('start-btn').addEventListener('click', () => openEditor({ fresh: true }));
  $('home-btn').addEventListener('click', () => {
    if (saved) openMyCard();
    else openWelcome();
  });

  $('qr-mode').addEventListener('change', onModeChange);
  $('act-image').addEventListener('click', onSaveImage);
  $('act-vcf').addEventListener('click', onAddContact);
  $('act-share').addEventListener('click', onShareLink);
  $('act-edit').addEventListener('click', () => openEditor());

  $('celebrate-close').addEventListener('click', closeCelebrate);
  $('celebrate').addEventListener('click', (e) => {
    if (e.target === $('celebrate')) closeCelebrate();
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeCelebrate();
  });

  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible' && !$('view-card').hidden) requestWakeLock();
  });

  setupTilt();
  setupInstall();

  if (saved) {
    openMyCard();
    maybeShowIosHint();
  } else {
    openWelcome();
  }
}

// The vendored QR script is `defer`, so it has run before this module executes.
init();
